   else if(b==4){int s=Step(u,3);heroMaterial.SetFloat("_Mode",s==0?0:1);triangleObject.SetActive(s==2);readout.text=s==0?"재질: 텍스처 + 셰이더":s==1?"기하: 정점 + 삼각형":"LOD: 거리에 맞는 메시 선택";meaning.text="현재 모델의 상세 수준을 바꿨다는 측정은 아닙니다.";kind.text=s==2?"현재 화면\nLOD 선택 개념도":"현재 화면\n우리 표면 셰이더";if(s==2){Box(new Vector3(3.1f,1.7f,-.6f),4.6f,3.6f,Teal);Tag(new Vector3(3.2f,3.6f,-.6f),"기하 표현 선택",White,-180,-50);} }
   else if(b==8||b==9){currentBuffer.Clear();var p=PipelineMath.TriangleAt(.4,new P3(.3,.75,.6));for(int i=0;i<p.Length;i++)p[i].clip.x+=Mathf.Lerp(-.12f,.12f,u);PipelineMath.Draw(currentBuffer,p,new PRasterOptions());Present(currentBuffer);if(b==8){readout.text="96 × 54 샘플의 실제 설명용 색 버퍼";meaning.text="각 칸에는 최종 색을 저장합니다.";Code(C("index",Teal)+" = y × width + x",C("color[index]",Green)+" = RGB");}else {kind.text="현재 화면\n버퍼 교환 개념도";Code(C(Step(u,2)==0?"앞 버퍼: 읽는 중":"앞 버퍼: 완성 그림",Teal),C(Step(u,2)==0?"뒤 버퍼: 그리는 중":"뒤 버퍼: 다음 그림",Green),"완성 뒤 present");readout.text="읽는 그림과 만드는 그림의 역할 분리";meaning.text="표시 시점 동기화는 별도의 설정입니다.";} }
