   else if(b==18||b==19){P4 p=new P4(.6,.5,0);var m=PMatrix.RotateY(u*.65)*PMatrix.Translation(0,0,3);var v=PMatrix.Translation(0,0,1);var projection=PMatrix.Projection(16.0/9,60,1,20,false);P4 model=m.Transform(p),view=v.Transform(model),clip=projection.Transform(view);int s=Step(u,4);P3 q=s==0?p.xyz:s==1?model.xyz:s==2?view.xyz:PipelineMath.Divide(clip);lastNumericVertices=new[]{p.xyz,model.xyz,view.xyz,clip.xyz};Dot(At(q*.5),Yellow,.17f);Arrow(At(new P3()),At(q*.5),Teal);Tag(At(q*.5),s==3?"원근 나눗셈 뒤":new[]{"모델","월드","뷰"}[s],Yellow,20,-60);Code(C("pModel × M",Teal),C("       × V",Green),C("       × P",Blue),"= pClip");readout.text="행벡터 관례: p × M × V × P";meaning.text=b==19?"미리 결합한 M × V × P도 같은 결과입니다.":"위치와 보간할 속성을 함께 다음 단계로 보냅니다.";}
   else if(b>=20&&b<=23){ClipDiagram(b,u);}
