   else if(b==28){bool correct=Step(u,2)==1;ShowTriangle(u,correct);readout.text=correct?"원근 보정: Σ(λᵢ aᵢ / wᵢ) / Σ(λᵢ / wᵢ)":"단순 화면 보간: Σ λᵢ aᵢ";meaning.text="보간한 법선은 길이가 달라져 다시 정규화합니다.";Code(C(correct?"perspective-correct":"affine interpolation",correct?Green:Red),"w = [1, 2, 4]", "λ = [0.25, 0.25, 0.5]",correct?"속성 가중치 = [0.5, 0.25, 0.25]":"속성 가중치 = λ");}
