  void VertexInputs(int b,float u){
   kind.text="현재 화면\n정점 데이터 해설";Dot(heroHome+new Vector3(0,2,-.4f),Yellow,.13f);Arrow(heroHome+new Vector3(.2f,2,-.4f),new Vector3(-.6f,2,-.4f),Teal);
   if(b==12){Code(C("Model / View / Projection",Blue),C("Light / Material",Yellow),"여러 정점이 함께 쓰는 상태");readout.text="공통 상태 + 정점마다 다른 입력";meaning.text="상태는 이번 그리기 작업의 계산 조건입니다.";}
   if(b==13||b==14){Code(C("position · 위치",Teal),C("normal · 표면 방향",Blue),C("uv · 텍스처 좌표",Green),b==14?C("tangent.xyz + handedness",Yellow):"color · 정점 색");readout.text=b==14?"B = h × (N × T)":"한 정점은 위치 외에도 여러 속성을 가집니다.";meaning.text=b==14?"부호 h는 UV의 거울 대칭 방향을 보관합니다.":"위치와 표면 정보가 함께 메시를 이룹니다.";}
   if(b==15){Box(new Vector3(2.8f,3.6f,-.5f),4,1,Teal);Tag(new Vector3(2.8f,3.6f,-.5f),"화면 좌표 HUD",Teal,-180,-25);Arrow(new Vector3(2,.2f,-.5f),new Vector3(3.8f,1.7f,-.5f),Green);readout.text="UI에도 3D에도 필요한 속성만 선택";meaning.text="조명을 쓰지 않는다면 법선 입력을 생략할 수 있습니다.";}
   if(b==16){Code(C("UV0 → 표면 / 노멀 맵",Green),C("UV1 → 라이트맵",Teal),C("indices + weights → 본",Yellow),"4개 영향은 예제의 설정");readout.text="접선은 노멀 맵 · 두 번째 UV는 라이트맵";meaning.text="이 두 데이터의 역할을 구분합니다.";}
   if(b==17){int i=Mathf.RoundToInt(2*u);int address=1000+i*32+12;Code(C("base = 1000",Teal),"stride = 32 byte", "normal offset = 12 byte",C("address = "+address,Yellow));readout.text="주소 = 시작 + 정점 번호 × 간격 + 속성 위치";meaning.text=Step(u,2)==0?"AoS: 정점별 속성을 나란히":"SoA: 같은 속성을 정점 순서로";for(int j=0;j<3;j++){Vector3 p=new Vector3(2.6f,3.5f-j*1.35f,-.5f);Box(p,4.5f,.9f,j==i?Yellow:Muted);Tag(p,Step(u,2)==0?"P"+j+"  N"+j+"  UV"+j:"P"+j+"  P"+(j+1)+"  P"+(j+2),j==i?Yellow:White,-185,-25);}}
  }
  void ClipDiagram(int b,float u){
   kind.text="현재 화면\n실제 클리핑 계산";var p=new[]{new PVertex(new P4(-.5,-.6,.3),new P2(0,0),new P3(.3,.7,.6)),new PVertex(new P4(1.1+.8*u,-.4,.3),new P2(1,0),new P3(.3,.7,.6)),new PVertex(new P4(.1,.8,.3),new P2(.5,1),new P3(.3,.7,.6))};var clipped=PipelineMath.Clip(p);Box(At(new P3()),3.6f,3.6f,Muted);for(int i=0;i<3;i++)Path(Red,At(p[i].clip.xyz),At(p[(i+1)%3].clip.xyz));for(int i=0;i<clipped.Count;i++){Path(Green,At(clipped[i].clip.xyz),At(clipped[(i+1)%clipped.Count].clip.xyz));Dot(At(clipped[i].clip.xyz),Yellow,.11f);}lastNumericVertices=new P3[clipped.Count];for(int i=0;i<clipped.Count;i++)lastNumericVertices[i]=clipped[i].clip.xyz;
   if(b==20){Code(C("−w ≤ x, y ≤ w",Teal),C("0 ≤ z ≤ w",Blue),"D3D 클립 범위", "잘라낸 뒤 x/w, y/w, z/w");readout.text="동차좌표에서 경계와 교차점을 먼저 계산";meaning.text="화면 밖 부분만 제거하고 보이는 다각형을 남깁니다.";}
   else if(b==21){int s=Step(u,4);string[] rows={"안 → 안: 시작점","밖 → 밖: 출력 없음","밖 → 안: 교차점","안 → 밖: 시작점 + 교차점"};for(int i=0;i<4;i++)code.text+=(i==s?"▶ ":"   ")+C(rows[i],i==s?Yellow:White)+"\n\n";DimHero();readout.text="Sutherland–Hodgman · 시작점 출력 방식";meaning.text="모든 변을 같은 규칙으로 한 바퀴 순회합니다.";}
   else if(b==22){Code("x: 0 → 2",C("경계: x = 1",Green),C("t = (1−0)/(2−0) = 0.5",Yellow),"UV도 같은 t로 보간");readout.text="중복점 정리 → 서로 다른 점 3개 이상 → 넓이 확인";meaning.text="경계에 닿기만 하는 넓이 0의 삼각형은 그리지 않습니다.";}
   else{currentBuffer.Clear();PipelineMath.Draw(currentBuffer,p,new PRasterOptions{scissorX=24,scissorY=8,scissorWidth=48,scissorHeight=40});Present(currentBuffer);readout.text="Scissor: 이미 정해진 화면 사각형 안만 기록";meaning.text="가드 밴드는 측면 처리 여유이며 near / w 검사를 없애지 않습니다.";kind.text="현재 화면\n우리 가위 영역 검사";Code(C("Scissor · 화면 영역",Green),C("Frustum · 3D 클립 범위",Blue),"서로 다른 단계의 조건");}
  }
  void Culling(int b,float u){
   if(b==25){bool reflected=Step(u,2)==1;float sign=reflected?-1:1;Vector3 windingCenter=At(new P3());Vector3[] vs={windingCenter+new Vector3(-1.3f*sign,-1,0),windingCenter+new Vector3(1.3f*sign,-1,0),windingCenter+new Vector3(0,1.3f,0)};for(int i=0;i<3;i++){Path(Teal,vs[i],vs[(i+1)%3]);Arrow(Vector3.Lerp(vs[i],vs[(i+1)%3],.2f),Vector3.Lerp(vs[i],vs[(i+1)%3],.65f),Yellow);Dot(vs[i],White);Tag(vs[i],i.ToString(),White,15,-30);}kind.text="현재 화면\n정점 순서 해설";readout.text=reflected?"x 반사 → 같은 정점 번호의 순서 반전":"정점 0 → 1 → 2를 같은 순서로 연결";meaning.text="CW / CCW 중 어느 쪽이 앞면인지는 별도 설정입니다.";Code(C("화면에 투영된 정점 순서",Teal),"반사 변환: x → −x",C("좌표계 이름만으로 앞면 결정 불가",Yellow));return;}
   kind.text="현재 화면\n면 방향의 수치 실험";double a=Math.PI*u;P3 n=new P3(Math.Cos(a),0,Math.Sin(a));P3 eye=new P3(2,0,0),p=new P3();if(b==26){n=new P3(1,0,0);eye=new P3(Step(u,2)==0?2:-2,0,0);}double dot=PipelineMath.BackfaceDot(n,p,eye);Vector3 center=At(p);Arrow(center,At(n),dot<=0?Green:Red);Dot(At(eye),Teal);Tag(At(eye),"시점",Teal,-50,-55);Path(Muted,center+new Vector3(0,-1.2f,0),center+new Vector3(0,1.2f,0));readout.text="N · (면의 점 − 시점) = "+N(dot)+ (dot>0?" → 뒷면":" → 앞면");meaning.text=b==24?"닫힌 불투명 물체와 얇은 양면 표면은 설정이 다릅니다.":b==25?"앞면 와인딩은 설정이며 거울 변환은 순서를 뒤집습니다.":"원근 시점에서는 법선의 z 부호만으로 판단할 수 없습니다.";
   if(b==25){Code(C("CCW / CW: 앞면 설정",Teal),"음의 행렬식 변환",C("→ 꼭짓점 순서 뒤집힘",Yellow));}else if(b==26){Code("N = (1, 0, 0)","eye = (2, 0, 0)",C("N · (p − eye) = −2",Green),"eye = (−2, 0, 0) → +2");}
  }
  void Transparency(float u){
   int s=Step(u,3);currentBuffer.Clear();var blue=PipelineMath.TriangleAt(.65,new P3(0,0,1));var red=PipelineMath.TriangleAt(.3,new P3(1,0,0));PipelineMath.Draw(currentBuffer,blue,new PRasterOptions());PipelineMath.Draw(currentBuffer,red,new PRasterOptions{alpha=.25,alphaTest=s==0,depthWrite=s==0,cutoff=.5});Present(currentBuffer);if(s==0){readout.text="Alpha test: α 0.25 < 기준 0.5 → 버림";meaning.text="버린 샘플은 색과 깊이를 쓰지 않습니다.";}else{readout.text="빨강 × 0.25 + 파랑 × 0.75 = (0.25, 0, 0.75)";meaning.text=s==1?"Alpha blend는 배경색과 섞습니다.":"투명 표면은 깊이 기록과 그리기 순서를 함께 정해야 합니다.";}Code(C(s==0?"discard":"src × α + dst × (1−α)",Yellow),s==0?"depth unchanged":"depth write OFF",s==2?"보통 뒤에서 앞으로":"같은 표면과 배경");
   if(s==2){currentBuffer.Clear();for(int i=0;i<currentBuffer.color.Length;i++)currentBuffer.color[i]=new P3();bool correct=u<.88f;var opts=new PRasterOptions{alpha=.5,depthWrite=false};PipelineMath.Draw(currentBuffer,correct?blue:red,opts);PipelineMath.Draw(currentBuffer,correct?red:blue,opts);Present(currentBuffer);readout.text=correct?"뒤 파랑 → 앞 빨강: (0.5, 0, 0.25)":"앞 빨강 → 뒤 파랑: (0.25, 0, 0.5)";}
  }
  void ApplyShaders(int b,float u){
   heroMaterial.SetVector("_LightPosition",new Vector4(-5.2f+u*1.2f,3,-3,1));triangleObject.SetActive(b>=35&&b<=47);triangleMaterial.SetVector("_LightPosition",new Vector4(2.2f+u*2,1.7f,-1.1f,1));
   if(b>=30&&b<=34){heroMaterial.SetFloat("_Mode",0);ShowTriangle(u,true);string[] rows=b==30?new[]{"데이터 입력", "정점 프로그램", "픽셀 프로그램"}:b==31?new[]{C("float4 position : POSITION;",Teal),C("float2 uv : TEXCOORD0;",Green),C("float4 clip : SV_Position;",Blue)}:b==32?new[]{"output.position =",C("  mul(input.position, M);",Yellow),"output.uv = input.uv;"}:b==33?new[]{C("texel = map.Sample(sampler, uv)",Green),"texel × tint",C("(.8, .4, .2) × (1, .5, 1)",Teal),"= (.8, .2, .2)"}:new[]{C("입력 POSITION",Teal),C("출력 SV_Position",Blue),C("픽셀 출력 SV_Target",Green)};Code(rows);readout.text=b==34?"과거 예제 표기 → 현재 HLSL의 역할별 시맨틱":"같은 위치와 UV를 이어서 한 표면을 만듭니다.";meaning.text=b==32?"여기서 M은 행벡터용 행렬입니다.":"색 데이터와 위치 데이터의 연결을 따라갑니다.";}
   else if(b==35){int s=Step(u,2);heroMaterial.SetFloat("_Mode",s);triangleMaterial.SetFloat("_Mode",s);readout.text=s==0?"Unlit: 텍스처 색":"Lit: 재질 × 조명 + 정반사";meaning.text="같은 UV로 읽더라도 난반사와 정반사의 역할은 다릅니다.";}
   else if(b==36||b==37||b==38){Vector3 p=triangleObject.transform.position;Vector3 l=new Vector3(2.2f+u*2,1.7f,-1.1f);Arrow(p,l,Yellow);Arrow(p,p+Vector3.back*1.3f,Blue);Tag(p+Vector3.back*1.3f,"N",Blue,15,-45);if(b==36){Code(C("L = normalize(light − p)",Yellow),C("V = normalize(eye − p)",Teal),"H = normalize(L + V)","d=1, R=4 → 1−d/R = .75");readout.text="L: 빛 쪽 · V: 시점 쪽 · H: 두 방향의 중간";meaning.text="이 예제는 선형 범위 감쇠를 사용합니다.";}else if(b==37){Code(C("Cd × (ambient + light × N·L)",Teal),C("+ Cs × light × (N·H)^p",Yellow),"N·L ≤ 0 → 직접광 0");readout.text="Blinn–Phong · 같은 공간의 정규화된 방향";meaning.text="선형 색에서 합산하며 환경광은 한 번만 더합니다.";}else{Code("난반사 .5 × (.75 × .8 + .1)",C("= .35",Teal),"정반사 .4 × .75 × .2 = .06",C("합계 = .41",Yellow));readout.text="작은 스칼라 예제로 항마다 계산";meaning.text="RGB라면 같은 계산을 각 채널에서 합니다.";} }
   else if(b==39||b==40){bool pre=b==40?Step(u,2)==1:Step(u,2)==0;triangleMaterial.SetFloat("_Mode",pre?2:1);Code(pre?C("정점에서 비선형 계산",Yellow):C("보간 뒤 픽셀에서 계산",Green),"끝점: +0.5, −0.5",pre?"먼저 clamp → 중간 .25":"먼저 보간 → clamp = 0", "보간한 L / N / H 다시 정규화");readout.text=b==39?"계산을 옮기면 보간되는 값과 근사가 달라집니다.":"clamp와 보간의 순서를 바꾸면 결과가 다릅니다.";meaning.text="성능 수치는 현재 하드웨어에서 별도 측정해야 합니다.";}
   else if(b==41||b==42){triangleObject.SetActive(false);Vector3 o=At(new P3());P3 correct=new P3(.5,1,0).Unit(),wrong=new P3(2,1,0).Unit();Arrow(o,At(correct),Green);Arrow(o,At(wrong),Red);if(b==41){Code(C("V = normalize(−viewPosition.xyz)",Teal),"위치: w = 1", "방향: w = 0", "서로 같은 공간으로");readout.text="뷰 공간에서는 시점이 원점입니다.";meaning.text="위치의 w까지 포함해 정규화하지 않습니다.";}else{Code(C("normal → inverseTranspose(M)",Green),"비균일 확대: x × 2",C("틀린 방향 "+F(wrong),Red),C("법선 "+F(correct),Green));readout.text="위치 변환과 법선 변환의 차이";meaning.text="수직 관계를 보존하려면 역전치가 필요합니다.";} }
   else if(b==43){bool vertex=Step(u,2)==0;triangleMaterial.SetFloat("_Mode",vertex?2:1);triangleMaterial.SetVector("_LightPosition",new Vector4(3.2f,1.7f,-1.1f,1));triangleMaterial.SetColor("_BaseColor",Color.black);triangleMaterial.SetColor("_SpecColor",Color.white);triangleMaterial.SetFloat("_Ambient",0);readout.text=vertex?"Gouraud: 정점의 조명값을 보간":"Phong shading: 보간한 방향으로 픽셀 조명";meaning.text="같은 3정점 삼각형 · 같은 빛 · 같은 시점";Code(vertex?C("모서리 정반사 → 거의 0",Red):C("중심 정반사 피크 → 보임",Green),"중앙은 N = H", "중앙 pow(N·H, 64) = 1");}
   else if(b==44||b==45){int lights=Step(u,2)==0?1:3;heroMaterial.SetFloat("_ThreeLights",lights==3?1:0);triangleMaterial.SetFloat("_ThreeLights",lights==3?1:0);heroMaterial.SetFloat("_Mode",2);triangleMaterial.SetFloat("_Mode",2);Code(C("diff = ambient",Teal),"for each light:","  diff += directDiffuse", "  spec += directSpecular");readout.text=lights+"개 광원 · 환경광은 한 번만";meaning.text=b==44?"픽셀 단계는 준비된 조명색을 같은 방식으로 사용합니다.":"루프를 펼칠지 여부는 대상 환경에서 확인합니다.";}
   else if(b==46||b==47){triangleMaterial.SetFloat("_Mode",3);heroMaterial.SetFloat("_Mode",3);Vector3 p=triangleObject.transform.position;Arrow(p,p+Vector3.right,Teal);Arrow(p,p+Vector3.up,Green);Arrow(p,p+Vector3.back,Blue);Code(C("B = h × cross(N, T)",Green),C("n = normalize(2 × rgb − 1)",Blue),"nWorld = xT + yB + zN", "L / H도 정규화");readout.text=b==46?"표면 좌표계의 T · B · N으로 빛을 해석":"선형 노멀 데이터 → 디코딩 → 정규화";meaning.text="정규직교 기저에서만 전치가 역변환입니다.";}
   else if(b>=48&&b<=50){skinObject.SetActive(true);float angle=95*u;skinMaterial.SetMatrix("_Bone0",Matrix4x4.identity);skinMaterial.SetMatrix("_Bone1",Matrix4x4.Rotate(Quaternion.Euler(0,0,angle)));skinMaterial.SetFloat("_Mode",b==50?3:1);skinMaterial.SetVector("_LightPosition",new Vector4(2,3,-4,1));rig.Sample(shot.clip,Mathf.Lerp(shot.clipIn,shot.clipOut,u));kind.text="현재 화면\n본 변형 + 우리 셰이더";Vector3 root=skinObject.transform.position;Arrow(root,root+Vector3.right*1.7f,Blue);Arrow(root,root+Quaternion.Euler(0,0,angle)*Vector3.right*1.7f,Green);if(b==48)Code(C("uint4 bones : BLENDINDICES",Yellow),C("float4 weights : BLENDWEIGHT",Teal),"boneMatrix[boneIndex]", "4개 / 40개는 예제 설정");else if(b==49)Code(C("Mblend = Σ wi × Mi",Yellow),"[1 × 4] × [4 × 3] = [1 × 3]", "위치 w=1 · 법선 w=0", "변형 → modelToClip");else Code(C("skin N, T",Teal),"normalize N", "T를 N에 수직으로 정리",C("B = h × cross(N, T)",Green));readout.text="같은 본 변환이 위치와 표면 기준축을 연결";meaning.text=b==50?"혼합 법선은 근사이며 비균일 확대 조건을 구분합니다.":"오른쪽 팔은 2개 본을 합산하는 실제 정점 셰이더입니다.";}
   else if(b==51){int s=Step(u,4);heroMaterial.SetFloat("_Mode",s==0?0:s<3?s==1?1:3:3);if(s==3)rig.Sample(shot.clip,Mathf.Lerp(shot.clipIn,shot.clipOut,u));string[] names={"텍스처만","조명","노멀 맵","스키닝 + 노멀 맵"};readout.text=names[s]+" · 같은 모델과 표면 데이터";meaning.text="정점은 위치를 준비하고 픽셀은 색을 완성합니다.";}
